use std::{fs::{self,OpenOptions},io::Write,path::PathBuf};
fn main(){let run=||->Result<(),String>{let p=PathBuf::from(std::env::args().nth(1).ok_or("ABSOLUTE_CONFIG_REQUIRED")?);if !p.is_absolute(){return Err("ABSOLUTE_CONFIG_REQUIRED".into())}let cfg:baal_settlement_restore_replay::Config=serde_json::from_slice(&fs::read(p).map_err(|_|"CONFIG_READ")?).map_err(|_|"CONFIG_JSON")?;let report=baal_settlement_restore_replay::run(&cfg)?;let mut out=OpenOptions::new().write(true).create_new(true).open(&cfg.output).map_err(|_|"FRESH_OUTPUT_REQUIRED")?;out.write_all(&serde_json::to_vec_pretty(&report).map_err(|_|"OUTPUT_JSON")?).and_then(|_|out.sync_all()).map_err(|_|"OUTPUT_WRITE")?;println!("{}",serde_json::json!({"elapsedMs":report["elapsedMs"],"stateHash":report["stateHash"],"journalRecords":report["evidence"]["journalRecords"],"allOriginalCheckpointsVerified":report["evidence"]["allOriginalCheckpointsVerified"],"authoritativeOverlayApplied":report["evidence"]["authoritativeOverlayApplied"],"archivedWalletParityVerified":report["archivedWalletParityVerified"],"perBookProcessesSpawned":0,"networkRequests":0,"competitionOrders":0}));Ok(())};if let Err(e)=run(){eprintln!("{e}");std::process::exit(1)}}
